-- seed_exercises_v2.sql — THAY TOÀN BỘ 40 bài tập cũ (seed.sql + seed_batch2/3/4) bằng 40 bài ít trùng chuyển động.
-- Phân bố: Ngực 6 | Lưng 7 | Vai 4 | Chân 8 | Tay 6 | Bụng 5 | Toàn thân/Cardio 4.
-- id sau khi nạp: Ngực 1-6, Lưng 7-13, Vai 14-17, Chân 18-25, Tay 26-31, Bụng 32-36, Toàn thân 37-40.
-- CHẠY MỘT LẦN, thay cho cả 4 file seed cũ (không chạy thêm seed_batch2/3/4 sau file này).
-- Cảnh báo: file này XÓA hết bảng exercises (kể cả image_url/video_url đã nhập). Nếu bảng workout_plan_exercises /
-- workout_logs đã có dữ liệu thì phải xóa các bảng đó trước (xem 2 dòng comment bên dưới), vì id bài tập sẽ đổi.
USE gymsmart;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
-- DELETE FROM workout_logs;            -- bỏ comment nếu bảng đã tồn tại và có dữ liệu
-- DELETE FROM workout_plan_exercises;  -- bỏ comment nếu bảng đã tồn tại và có dữ liệu
TRUNCATE TABLE exercises;
SET FOREIGN_KEY_CHECKS = 1;

